const QUESTIONS=[{"id":"F1","kind":"fiscal","stem":"A recession leaves construction workers unemployed. Congress funds repairs to bridges while leaving tax rates unchanged.","targets":[0,1],"outcome":"expand","choices":["Infrastructure purchases directly raise demand and employment; taxes need not change.","Because taxes are unchanged, federal purchases must automatically become lower.","The policy has no possible effect on demand because only the Federal Reserve influences economic activity.","Every increase in public spending immediately creates a budget surplus, regardless of tax collections."],"answer":"Infrastructure purchases directly raise demand and employment; taxes need not change.","hint":"Identify whether each fiscal lever increases, decreases, or stays unchanged; then trace demand.","explain":"Infrastructure purchases directly raise demand and employment; taxes need not change.","source":"https://www.cbo.gov/topics/economy","where":"CBO Economy: compare tax changes, transfer payments, government purchases, and demand effects; weigh competing levers."},{"id":"F2","kind":"fiscal","stem":"Inflation is accelerating. Congress raises income taxes and reduces discretionary spending.","targets":[1,-1],"outcome":"contract","choices":["Both changes withdraw purchasing power and reduce aggregate demand.","The tax decision directly changes the Fed’s policy interest rate without any Fed action.","Tax and spending decisions can never work in opposite directions, regardless of the size of either change.","Every tax reduction must reduce consumer purchasing power because households owe less to the Treasury."],"answer":"Both changes withdraw purchasing power and reduce aggregate demand.","hint":"Identify whether each fiscal lever increases, decreases, or stays unchanged; then trace demand.","explain":"Both changes withdraw purchasing power and reduce aggregate demand.","source":"https://www.cbo.gov/topics/economy","where":"CBO Economy: compare tax changes, transfer payments, government purchases, and demand effects; weigh competing levers."},{"id":"F3","kind":"fiscal","stem":"Household demand collapses. Congress temporarily increases unemployment insurance and offers a refundable tax credit.","targets":[-1,1],"outcome":"expand","choices":["Benefits support spending and a credit lowers net tax burdens; both support demand.","With taxes lower and spending higher, the government necessarily eliminates all inflation and unemployment.","Because the plan concerns federal revenue, Congress must first obtain approval from the Federal Reserve.","The policy guarantees an identical effect on every household, business, and sector of the economy."],"answer":"Benefits support spending and a credit lowers net tax burdens; both support demand.","hint":"Identify whether each fiscal lever increases, decreases, or stays unchanged; then trace demand.","explain":"Benefits support spending and a credit lowers net tax burdens; both support demand.","source":"https://www.cbo.gov/topics/economy","where":"CBO Economy: compare tax changes, transfer payments, government purchases, and demand effects; weigh competing levers."},{"id":"F4","kind":"fiscal","stem":"Consumer prices are rising rapidly. Congress cuts spending but also cuts taxes by a similar amount.","targets":[-1,-1],"outcome":"mixed","choices":["The spending cut restrains demand while the tax cut supports it; the net effect is uncertain.","Because taxes are lower, federal purchases must automatically become higher.","Because the plan concerns federal revenue, Congress must first obtain approval from the Federal Reserve.","Every tax reduction must reduce consumer purchasing power because households owe less to the Treasury."],"answer":"The spending cut restrains demand while the tax cut supports it; the net effect is uncertain.","hint":"Identify whether each fiscal lever increases, decreases, or stays unchanged; then trace demand.","explain":"The spending cut restrains demand while the tax cut supports it; the net effect is uncertain.","source":"https://www.cbo.gov/topics/economy","where":"CBO Economy: compare tax changes, transfer payments, government purchases, and demand effects; weigh competing levers."},{"id":"F5","kind":"fiscal","stem":"Congress raises taxes to finance an equally sized new highway program during a recession.","targets":[1,1],"outcome":"mixed","choices":["The spending increase stimulates demand while higher taxes pull in the opposite direction.","The tax decision directly changes the Fed’s policy interest rate without any Fed action.","This fiscal choice changes only bank reserve requirements and cannot affect disposable income or purchases.","The policy guarantees an identical effect on every household, business, and sector of the economy."],"answer":"The spending increase stimulates demand while higher taxes pull in the opposite direction.","hint":"Identify whether each fiscal lever increases, decreases, or stays unchanged; then trace demand.","explain":"The spending increase stimulates demand while higher taxes pull in the opposite direction.","source":"https://www.cbo.gov/topics/economy","where":"CBO Economy: compare tax changes, transfer payments, government purchases, and demand effects; weigh competing levers."},{"id":"F6","kind":"fiscal","stem":"A slowdown prompts a temporary payroll-tax reduction; federal purchases remain unchanged.","targets":[-1,0],"outcome":"expand","choices":["A tax cut increases take-home pay, potentially increasing private spending.","With taxes lower and spending unchanged, the government necessarily eliminates all inflation and unemployment.","Tax and spending decisions can never work in opposite directions, regardless of the size of either change.","Every increase in public spending immediately creates a budget surplus, regardless of tax collections."],"answer":"A tax cut increases take-home pay, potentially increasing private spending.","hint":"Identify whether each fiscal lever increases, decreases, or stays unchanged; then trace demand.","explain":"A tax cut increases take-home pay, potentially increasing private spending.","source":"https://www.cbo.gov/topics/economy","where":"CBO Economy: compare tax changes, transfer payments, government purchases, and demand effects; weigh competing levers."},{"id":"F7","kind":"fiscal","stem":"Inflation is persistent. Congress delays a major federal construction program; tax law is unchanged.","targets":[0,-1],"outcome":"contract","choices":["Postponing purchases reduces government demand without changing taxes.","Because taxes are unchanged, federal purchases must automatically become higher.","This fiscal choice changes only bank reserve requirements and cannot affect disposable income or purchases.","Every tax reduction must reduce consumer purchasing power because households owe less to the Treasury."],"answer":"Postponing purchases reduces government demand without changing taxes.","hint":"Identify whether each fiscal lever increases, decreases, or stays unchanged; then trace demand.","explain":"Postponing purchases reduces government demand without changing taxes.","source":"https://www.cbo.gov/topics/economy","where":"CBO Economy: compare tax changes, transfer payments, government purchases, and demand effects; weigh competing levers."},{"id":"F8","kind":"fiscal","stem":"Congress raises tax rates and leaves spending unchanged to cool consumer demand.","targets":[1,0],"outcome":"contract","choices":["Higher taxes reduce disposable income and tend to moderate spending.","The tax decision directly changes the Fed’s policy interest rate without any Fed action.","The policy has no possible effect on demand because only the Federal Reserve influences economic activity.","The policy guarantees an identical effect on every household, business, and sector of the economy."],"answer":"Higher taxes reduce disposable income and tend to moderate spending.","hint":"Identify whether each fiscal lever increases, decreases, or stays unchanged; then trace demand.","explain":"Higher taxes reduce disposable income and tend to moderate spending.","source":"https://www.cbo.gov/topics/economy","where":"CBO Economy: compare tax changes, transfer payments, government purchases, and demand effects; weigh competing levers."},{"id":"F9","kind":"fiscal","stem":"The economy is weak, but Congress cuts taxes and cuts infrastructure spending at the same time.","targets":[-1,-1],"outcome":"mixed","choices":["Lower taxes stimulate private demand while spending cuts directly restrain it.","With taxes lower and spending lower, the government necessarily eliminates all inflation and unemployment.","This fiscal choice changes only bank reserve requirements and cannot affect disposable income or purchases.","Every increase in public spending immediately creates a budget surplus, regardless of tax collections."],"answer":"Lower taxes stimulate private demand while spending cuts directly restrain it.","hint":"Identify whether each fiscal lever increases, decreases, or stays unchanged; then trace demand.","explain":"Lower taxes stimulate private demand while spending cuts directly restrain it.","source":"https://www.cbo.gov/topics/economy","where":"CBO Economy: compare tax changes, transfer payments, government purchases, and demand effects; weigh competing levers."},{"id":"F10","kind":"fiscal","stem":"After a natural disaster, Congress approves emergency rebuilding and offsets some costs with higher taxes.","targets":[1,1],"outcome":"mixed","choices":["Rebuilding stimulates demand; higher taxes counteract some of that stimulus.","Because taxes are higher, federal purchases must automatically become lower.","Tax and spending decisions can never work in opposite directions, regardless of the size of either change.","The policy guarantees an identical effect on every household, business, and sector of the economy."],"answer":"Rebuilding stimulates demand; higher taxes counteract some of that stimulus.","hint":"Identify whether each fiscal lever increases, decreases, or stays unchanged; then trace demand.","explain":"Rebuilding stimulates demand; higher taxes counteract some of that stimulus.","source":"https://www.cbo.gov/topics/economy","where":"CBO Economy: compare tax changes, transfer payments, government purchases, and demand effects; weigh competing levers."},{"id":"F11","kind":"fiscal","stem":"A recession leads Congress to raise spending on public transit and reduce income taxes.","targets":[-1,1],"outcome":"expand","choices":["Both policies support spending and employment during a downturn.","Because taxes are lower, federal purchases must automatically become lower.","The policy has no possible effect on demand because only the Federal Reserve influences economic activity.","Every increase in public spending immediately creates a budget surplus, regardless of tax collections."],"answer":"Both policies support spending and employment during a downturn.","hint":"Identify whether each fiscal lever increases, decreases, or stays unchanged; then trace demand.","explain":"Both policies support spending and employment during a downturn.","source":"https://www.cbo.gov/topics/economy","where":"CBO Economy: compare tax changes, transfer payments, government purchases, and demand effects; weigh competing levers."},{"id":"F12","kind":"fiscal","stem":"With unemployment low and prices climbing, Congress reduces purchases and raises tax rates.","targets":[1,-1],"outcome":"contract","choices":["Both policies work to reduce excess demand.","The tax decision directly changes the Fed’s policy interest rate without any Fed action.","Tax and spending decisions can never work in opposite directions, regardless of the size of either change.","Every tax reduction must reduce consumer purchasing power because households owe less to the Treasury."],"answer":"Both policies work to reduce excess demand.","hint":"Identify whether each fiscal lever increases, decreases, or stays unchanged; then trace demand.","explain":"Both policies work to reduce excess demand.","source":"https://www.cbo.gov/topics/economy","where":"CBO Economy: compare tax changes, transfer payments, government purchases, and demand effects; weigh competing levers."},{"id":"F13","kind":"fiscal","stem":"Lawmakers extend a tax deduction for businesses but freeze federal purchases.","targets":[-1,0],"outcome":"expand","choices":["A deduction reduces taxable income, lowering tax liability for eligible firms.","With taxes lower and spending unchanged, the government necessarily eliminates all inflation and unemployment.","Because the plan concerns federal revenue, Congress must first obtain approval from the Federal Reserve.","The policy guarantees an identical effect on every household, business, and sector of the economy."],"answer":"A deduction reduces taxable income, lowering tax liability for eligible firms.","hint":"Identify whether each fiscal lever increases, decreases, or stays unchanged; then trace demand.","explain":"A deduction reduces taxable income, lowering tax liability for eligible firms.","source":"https://www.cbo.gov/topics/economy","where":"CBO Economy: compare tax changes, transfer payments, government purchases, and demand effects; weigh competing levers."},{"id":"F14","kind":"fiscal","stem":"Congress lets a temporary household tax credit expire and does not change spending.","targets":[1,0],"outcome":"contract","choices":["Ending a credit raises net taxes for affected households and can reduce demand.","Because taxes are higher, federal purchases must automatically become higher.","Because the plan concerns federal revenue, Congress must first obtain approval from the Federal Reserve.","Every tax reduction must reduce consumer purchasing power because households owe less to the Treasury."],"answer":"Ending a credit raises net taxes for affected households and can reduce demand.","hint":"Identify whether each fiscal lever increases, decreases, or stays unchanged; then trace demand.","explain":"Ending a credit raises net taxes for affected households and can reduce demand.","source":"https://www.cbo.gov/topics/economy","where":"CBO Economy: compare tax changes, transfer payments, government purchases, and demand effects; weigh competing levers."},{"id":"F15","kind":"fiscal","stem":"An automatic unemployment-insurance program pays more benefits as layoffs rise; lawmakers pass no new spending law.","targets":[0,1],"outcome":"expand","choices":["Automatic stabilizers increase transfer payments during downturns without a new vote.","The spending decision directly changes the Fed’s policy interest rate without any Fed action.","This fiscal choice changes only bank reserve requirements and cannot affect disposable income or purchases.","The policy guarantees an identical effect on every household, business, and sector of the economy."],"answer":"Automatic stabilizers increase transfer payments during downturns without a new vote.","hint":"Identify whether each fiscal lever increases, decreases, or stays unchanged; then trace demand.","explain":"Automatic stabilizers increase transfer payments during downturns without a new vote.","source":"https://www.cbo.gov/topics/economy","where":"CBO Economy: compare tax changes, transfer payments, government purchases, and demand effects; weigh competing levers."},{"id":"F16","kind":"fiscal","stem":"As employment recovers, unemployment-insurance payments decline automatically; tax rates stay unchanged.","targets":[0,-1],"outcome":"contract","choices":["Automatic transfers fall as the economy improves, reducing fiscal support.","With taxes unchanged and spending lower, the government necessarily eliminates all inflation and unemployment.","Tax and spending decisions can never work in opposite directions, regardless of the size of either change.","Every increase in public spending immediately creates a budget surplus, regardless of tax collections."],"answer":"Automatic transfers fall as the economy improves, reducing fiscal support.","hint":"Identify whether each fiscal lever increases, decreases, or stays unchanged; then trace demand.","explain":"Automatic transfers fall as the economy improves, reducing fiscal support.","source":"https://www.cbo.gov/topics/economy","where":"CBO Economy: compare tax changes, transfer payments, government purchases, and demand effects; weigh competing levers."},{"id":"F17","kind":"fiscal","stem":"Congress increases public-school construction while keeping tax policy constant.","targets":[0,1],"outcome":"expand","choices":["Public investment increases purchases and can create short-run jobs.","Because taxes are unchanged, federal purchases must automatically become lower.","This fiscal choice changes only bank reserve requirements and cannot affect disposable income or purchases.","Every tax reduction must reduce consumer purchasing power because households owe less to the Treasury."],"answer":"Public investment increases purchases and can create short-run jobs.","hint":"Identify whether each fiscal lever increases, decreases, or stays unchanged; then trace demand.","explain":"Public investment increases purchases and can create short-run jobs.","source":"https://www.cbo.gov/topics/economy","where":"CBO Economy: compare tax changes, transfer payments, government purchases, and demand effects; weigh competing levers."},{"id":"F18","kind":"fiscal","stem":"During inflation, Congress cancels planned federal equipment orders and keeps taxes fixed.","targets":[0,-1],"outcome":"contract","choices":["Reduced purchases lower demand even when tax rates do not change.","The spending decision directly changes the Fed’s policy interest rate without any Fed action.","The policy has no possible effect on demand because only the Federal Reserve influences economic activity.","The policy guarantees an identical effect on every household, business, and sector of the economy."],"answer":"Reduced purchases lower demand even when tax rates do not change.","hint":"Identify whether each fiscal lever increases, decreases, or stays unchanged; then trace demand.","explain":"Reduced purchases lower demand even when tax rates do not change.","source":"https://www.cbo.gov/topics/economy","where":"CBO Economy: compare tax changes, transfer payments, government purchases, and demand effects; weigh competing levers."},{"id":"F19","kind":"fiscal","stem":"Congress reduces income taxes but increases spending on water systems during a downturn.","targets":[-1,1],"outcome":"expand","choices":["Both changes are expansionary fiscal actions, though actual outcomes depend on conditions.","With taxes lower and spending higher, the government necessarily eliminates all inflation and unemployment.","This fiscal choice changes only bank reserve requirements and cannot affect disposable income or purchases.","Every increase in public spending immediately creates a budget surplus, regardless of tax collections."],"answer":"Both changes are expansionary fiscal actions, though actual outcomes depend on conditions.","hint":"Identify whether each fiscal lever increases, decreases, or stays unchanged; then trace demand.","explain":"Both changes are expansionary fiscal actions, though actual outcomes depend on conditions.","source":"https://www.cbo.gov/topics/economy","where":"CBO Economy: compare tax changes, transfer payments, government purchases, and demand effects; weigh competing levers."},{"id":"F20","kind":"fiscal","stem":"To address inflation, Congress raises taxes while expanding a major subsidy program.","targets":[1,1],"outcome":"mixed","choices":["The tax increase restrains demand, but additional transfers can stimulate it.","Because taxes are higher, federal purchases must automatically become lower.","Tax and spending decisions can never work in opposite directions, regardless of the size of either change.","The policy guarantees an identical effect on every household, business, and sector of the economy."],"answer":"The tax increase restrains demand, but additional transfers can stimulate it.","hint":"Identify whether each fiscal lever increases, decreases, or stays unchanged; then trace demand.","explain":"The tax increase restrains demand, but additional transfers can stimulate it.","source":"https://www.cbo.gov/topics/economy","where":"CBO Economy: compare tax changes, transfer payments, government purchases, and demand effects; weigh competing levers."},{"id":"M1","kind":"monetary","stem":"During a recession, the Fed seeks easier borrowing and more lending.","targets":[-1,-1,1],"outcome":"expand","choices":["Lower policy rates, lower textbook reserve requirements, and bond purchases all tend to ease credit.","Because the Fed purchased bonds, Congress must automatically increase income tax rates.","The Fed can change the money supply only by changing federal income taxes.","The Fed’s policy tools cannot influence credit availability or economic demand."],"answer":"Lower policy rates, lower textbook reserve requirements, and bond purchases all tend to ease credit.","hint":"Rates and reserve requirements usually move opposite to expansion; bond purchases add reserves, sales remove them.","explain":"Lower policy rates, lower textbook reserve requirements, and bond purchases all tend to ease credit.","source":"https://www.federalreserve.gov/monetarypolicy.htm","where":"Federal Reserve Monetary Policy: interest-rate transmission and open-market purchases/sales; reserve requirement is a historical textbook lever (currently 0%)."},{"id":"M2","kind":"monetary","stem":"Inflation is above target; the Fed wants to slow credit growth.","targets":[1,1,-1],"outcome":"contract","choices":["Higher rates, higher textbook reserves, and bond sales tend to tighten credit.","The Fed raised its rate, so the government budget must balance immediately.","A higher policy rate necessarily increases borrowing because loans become cheaper.","Bond sales always add reserves to banks, whereas bond purchases always remove them."],"answer":"Higher rates, higher textbook reserves, and bond sales tend to tighten credit.","hint":"Rates and reserve requirements usually move opposite to expansion; bond purchases add reserves, sales remove them.","explain":"Higher rates, higher textbook reserves, and bond sales tend to tighten credit.","source":"https://www.federalreserve.gov/monetarypolicy.htm","where":"Federal Reserve Monetary Policy: interest-rate transmission and open-market purchases/sales; reserve requirement is a historical textbook lever (currently 0%)."},{"id":"M3","kind":"monetary","stem":"The Fed purchases Treasury securities while leaving its interest-rate target and reserve requirement unchanged.","targets":[0,0,1],"outcome":"expand","choices":["Bond purchases add reserves and generally support liquidity.","Bond purchases and bond sales have identical effects on banking-system reserves.","A lower policy rate necessarily reduces borrowing because loans become more expensive.","The reserve requirement is currently a routinely adjusted positive percentage for all banks."],"answer":"Bond purchases add reserves and generally support liquidity.","hint":"Rates and reserve requirements usually move opposite to expansion; bond purchases add reserves, sales remove them.","explain":"Bond purchases add reserves and generally support liquidity.","source":"https://www.federalreserve.gov/monetarypolicy.htm","where":"Federal Reserve Monetary Policy: interest-rate transmission and open-market purchases/sales; reserve requirement is a historical textbook lever (currently 0%)."},{"id":"M4","kind":"monetary","stem":"The Fed sells government bonds to remove liquidity, without changing its other two settings.","targets":[0,0,-1],"outcome":"contract","choices":["Bond sales withdraw reserves and tend to tighten money conditions.","Because the Fed sold bonds, Congress must automatically increase income tax rates.","A lower policy rate necessarily reduces borrowing because loans become more expensive.","Bond sales always add reserves to banks, whereas bond purchases always remove them."],"answer":"Bond sales withdraw reserves and tend to tighten money conditions.","hint":"Rates and reserve requirements usually move opposite to expansion; bond purchases add reserves, sales remove them.","explain":"Bond sales withdraw reserves and tend to tighten money conditions.","source":"https://www.federalreserve.gov/monetarypolicy.htm","where":"Federal Reserve Monetary Policy: interest-rate transmission and open-market purchases/sales; reserve requirement is a historical textbook lever (currently 0%)."},{"id":"M5","kind":"monetary","stem":"To discourage borrowing, the Fed raises its policy rate but does not change bond holdings or reserve requirements.","targets":[1,0,0],"outcome":"contract","choices":["Higher policy rates make borrowing more costly, reducing rate-sensitive spending.","The Fed raised its rate, so the government budget must balance immediately.","Changes in reserve requirements are voted on by the House and Senate, not the Fed.","The reserve requirement is currently a routinely adjusted positive percentage for all banks."],"answer":"Higher policy rates make borrowing more costly, reducing rate-sensitive spending.","hint":"Rates and reserve requirements usually move opposite to expansion; bond purchases add reserves, sales remove them.","explain":"Higher policy rates make borrowing more costly, reducing rate-sensitive spending.","source":"https://www.federalreserve.gov/monetarypolicy.htm","where":"Federal Reserve Monetary Policy: interest-rate transmission and open-market purchases/sales; reserve requirement is a historical textbook lever (currently 0%)."},{"id":"M6","kind":"monetary","stem":"To encourage investment, the Fed lowers its policy rate and leaves other tools steady.","targets":[-1,0,0],"outcome":"expand","choices":["Lower rates generally encourage borrowing and investment.","Bond purchases and bond sales have identical effects on banking-system reserves.","A higher policy rate necessarily increases borrowing because loans become cheaper.","The Fed’s policy tools cannot influence credit availability or economic demand."],"answer":"Lower rates generally encourage borrowing and investment.","hint":"Rates and reserve requirements usually move opposite to expansion; bond purchases add reserves, sales remove them.","explain":"Lower rates generally encourage borrowing and investment.","source":"https://www.federalreserve.gov/monetarypolicy.htm","where":"Federal Reserve Monetary Policy: interest-rate transmission and open-market purchases/sales; reserve requirement is a historical textbook lever (currently 0%)."},{"id":"M7","kind":"monetary","stem":"In a textbook scenario, the Fed lowers the reserve requirement, with rates and bond holdings unchanged.","targets":[0,-1,0],"outcome":"expand","choices":["A lower reserve ratio can increase banks’ capacity to lend in the textbook model.","Because the Fed not traded bonds, Congress must automatically increase income tax rates.","Changes in reserve requirements are voted on by the House and Senate, not the Fed.","Bond sales always add reserves to banks, whereas bond purchases always remove them."],"answer":"A lower reserve ratio can increase banks’ capacity to lend in the textbook model.","hint":"Rates and reserve requirements usually move opposite to expansion; bond purchases add reserves, sales remove them.","explain":"A lower reserve ratio can increase banks’ capacity to lend in the textbook model.","source":"https://www.federalreserve.gov/monetarypolicy.htm","where":"Federal Reserve Monetary Policy: interest-rate transmission and open-market purchases/sales; reserve requirement is a historical textbook lever (currently 0%)."},{"id":"M8","kind":"monetary","stem":"In a textbook scenario, the Fed raises reserve requirements while holding its other tools steady.","targets":[0,1,0],"outcome":"contract","choices":["A higher reserve ratio limits the deposits available for lending in the simplified model.","The Fed held steady its rate, so the government budget must balance immediately.","The Fed can change the money supply only by changing federal income taxes.","The reserve requirement is currently a routinely adjusted positive percentage for all banks."],"answer":"A higher reserve ratio limits the deposits available for lending in the simplified model.","hint":"Rates and reserve requirements usually move opposite to expansion; bond purchases add reserves, sales remove them.","explain":"A higher reserve ratio limits the deposits available for lending in the simplified model.","source":"https://www.federalreserve.gov/monetarypolicy.htm","where":"Federal Reserve Monetary Policy: interest-rate transmission and open-market purchases/sales; reserve requirement is a historical textbook lever (currently 0%)."},{"id":"M9","kind":"monetary","stem":"The Fed cuts rates but sells bonds at the same time, without changing reserve requirements.","targets":[-1,0,-1],"outcome":"mixed","choices":["Lower rates ease credit while bond sales remove reserves; effects compete.","Bond purchases and bond sales have identical effects on banking-system reserves.","Changes in reserve requirements are voted on by the House and Senate, not the Fed.","The Fed’s policy tools cannot influence credit availability or economic demand."],"answer":"Lower rates ease credit while bond sales remove reserves; effects compete.","hint":"Rates and reserve requirements usually move opposite to expansion; bond purchases add reserves, sales remove them.","explain":"Lower rates ease credit while bond sales remove reserves; effects compete.","source":"https://www.federalreserve.gov/monetarypolicy.htm","where":"Federal Reserve Monetary Policy: interest-rate transmission and open-market purchases/sales; reserve requirement is a historical textbook lever (currently 0%)."},{"id":"M10","kind":"monetary","stem":"The Fed raises rates but buys government securities, keeping reserve rules unchanged.","targets":[1,0,1],"outcome":"mixed","choices":["Higher rates tighten while purchases add liquidity; tools pull in different directions.","Because the Fed purchased bonds, Congress must automatically increase income tax rates.","A higher policy rate necessarily increases borrowing because loans become cheaper.","The reserve requirement is currently a routinely adjusted positive percentage for all banks."],"answer":"Higher rates tighten while purchases add liquidity; tools pull in different directions.","hint":"Rates and reserve requirements usually move opposite to expansion; bond purchases add reserves, sales remove them.","explain":"Higher rates tighten while purchases add liquidity; tools pull in different directions.","source":"https://www.federalreserve.gov/monetarypolicy.htm","where":"Federal Reserve Monetary Policy: interest-rate transmission and open-market purchases/sales; reserve requirement is a historical textbook lever (currently 0%)."},{"id":"M11","kind":"monetary","stem":"The Fed wants a strongly expansionary textbook policy mix after a severe contraction.","targets":[-1,-1,1],"outcome":"expand","choices":["All three textbook levers point toward easier credit.","Because the Fed purchased bonds, Congress must automatically increase income tax rates.","The Fed can change the money supply only by changing federal income taxes.","The Fed’s policy tools cannot influence credit availability or economic demand."],"answer":"All three textbook levers point toward easier credit.","hint":"Rates and reserve requirements usually move opposite to expansion; bond purchases add reserves, sales remove them.","explain":"All three textbook levers point toward easier credit.","source":"https://www.federalreserve.gov/monetarypolicy.htm","where":"Federal Reserve Monetary Policy: interest-rate transmission and open-market purchases/sales; reserve requirement is a historical textbook lever (currently 0%)."},{"id":"M12","kind":"monetary","stem":"The Fed wants a strongly contractionary textbook policy mix to restrain inflation.","targets":[1,1,-1],"outcome":"contract","choices":["All three textbook levers point toward tighter credit.","The Fed raised its rate, so the government budget must balance immediately.","A higher policy rate necessarily increases borrowing because loans become cheaper.","Bond sales always add reserves to banks, whereas bond purchases always remove them."],"answer":"All three textbook levers point toward tighter credit.","hint":"Rates and reserve requirements usually move opposite to expansion; bond purchases add reserves, sales remove them.","explain":"All three textbook levers point toward tighter credit.","source":"https://www.federalreserve.gov/monetarypolicy.htm","where":"Federal Reserve Monetary Policy: interest-rate transmission and open-market purchases/sales; reserve requirement is a historical textbook lever (currently 0%)."},{"id":"M13","kind":"monetary","stem":"Bond purchases increase reserves; the Fed simultaneously raises interest rates, with reserve rules unchanged.","targets":[1,0,1],"outcome":"mixed","choices":["Liquidity support and rate tightening operate in opposite directions.","Bond purchases and bond sales have identical effects on banking-system reserves.","A lower policy rate necessarily reduces borrowing because loans become more expensive.","The reserve requirement is currently a routinely adjusted positive percentage for all banks."],"answer":"Liquidity support and rate tightening operate in opposite directions.","hint":"Rates and reserve requirements usually move opposite to expansion; bond purchases add reserves, sales remove them.","explain":"Liquidity support and rate tightening operate in opposite directions.","source":"https://www.federalreserve.gov/monetarypolicy.htm","where":"Federal Reserve Monetary Policy: interest-rate transmission and open-market purchases/sales; reserve requirement is a historical textbook lever (currently 0%)."},{"id":"M14","kind":"monetary","stem":"The Fed sells bonds while lowering reserve requirements, holding its policy rate constant.","targets":[0,-1,-1],"outcome":"mixed","choices":["Bond sales tighten liquidity, but lower reserve requirements ease lending capacity.","Because the Fed sold bonds, Congress must automatically increase income tax rates.","A lower policy rate necessarily reduces borrowing because loans become more expensive.","Bond sales always add reserves to banks, whereas bond purchases always remove them."],"answer":"Bond sales tighten liquidity, but lower reserve requirements ease lending capacity.","hint":"Rates and reserve requirements usually move opposite to expansion; bond purchases add reserves, sales remove them.","explain":"Bond sales tighten liquidity, but lower reserve requirements ease lending capacity.","source":"https://www.federalreserve.gov/monetarypolicy.htm","where":"Federal Reserve Monetary Policy: interest-rate transmission and open-market purchases/sales; reserve requirement is a historical textbook lever (currently 0%)."},{"id":"M15","kind":"monetary","stem":"The Fed cuts its policy rate and buys bonds; reserve requirements stay unchanged.","targets":[-1,0,1],"outcome":"expand","choices":["Lower rates and asset purchases both support monetary expansion.","The Fed lowered its rate, so the government budget must balance immediately.","Changes in reserve requirements are voted on by the House and Senate, not the Fed.","The reserve requirement is currently a routinely adjusted positive percentage for all banks."],"answer":"Lower rates and asset purchases both support monetary expansion.","hint":"Rates and reserve requirements usually move opposite to expansion; bond purchases add reserves, sales remove them.","explain":"Lower rates and asset purchases both support monetary expansion.","source":"https://www.federalreserve.gov/monetarypolicy.htm","where":"Federal Reserve Monetary Policy: interest-rate transmission and open-market purchases/sales; reserve requirement is a historical textbook lever (currently 0%)."},{"id":"M16","kind":"monetary","stem":"The Fed raises its policy rate and sells bonds; reserve requirements remain unchanged.","targets":[1,0,-1],"outcome":"contract","choices":["Higher rates and bond sales both restrain borrowing and liquidity.","Bond purchases and bond sales have identical effects on banking-system reserves.","A higher policy rate necessarily increases borrowing because loans become cheaper.","The Fed’s policy tools cannot influence credit availability or economic demand."],"answer":"Higher rates and bond sales both restrain borrowing and liquidity.","hint":"Rates and reserve requirements usually move opposite to expansion; bond purchases add reserves, sales remove them.","explain":"Higher rates and bond sales both restrain borrowing and liquidity.","source":"https://www.federalreserve.gov/monetarypolicy.htm","where":"Federal Reserve Monetary Policy: interest-rate transmission and open-market purchases/sales; reserve requirement is a historical textbook lever (currently 0%)."},{"id":"M17","kind":"monetary","stem":"The Fed changes no tools despite a sudden drop in output.","targets":[0,0,0],"outcome":"neutral","choices":["Without a tool change, there is no new monetary impulse from these three levers.","Because the Fed not traded bonds, Congress must automatically increase income tax rates.","Changes in reserve requirements are voted on by the House and Senate, not the Fed.","Bond sales always add reserves to banks, whereas bond purchases always remove them."],"answer":"Without a tool change, there is no new monetary impulse from these three levers.","hint":"Rates and reserve requirements usually move opposite to expansion; bond purchases add reserves, sales remove them.","explain":"Without a tool change, there is no new monetary impulse from these three levers.","source":"https://www.federalreserve.gov/monetarypolicy.htm","where":"Federal Reserve Monetary Policy: interest-rate transmission and open-market purchases/sales; reserve requirement is a historical textbook lever (currently 0%)."},{"id":"M18","kind":"monetary","stem":"The Fed keeps rates unchanged but sells bonds and increases textbook reserve requirements.","targets":[0,1,-1],"outcome":"contract","choices":["Both reserve tightening and bond sales tend to constrain lending.","The Fed held steady its rate, so the government budget must balance immediately.","The Fed can change the money supply only by changing federal income taxes.","The reserve requirement is currently a routinely adjusted positive percentage for all banks."],"answer":"Both reserve tightening and bond sales tend to constrain lending.","hint":"Rates and reserve requirements usually move opposite to expansion; bond purchases add reserves, sales remove them.","explain":"Both reserve tightening and bond sales tend to constrain lending.","source":"https://www.federalreserve.gov/monetarypolicy.htm","where":"Federal Reserve Monetary Policy: interest-rate transmission and open-market purchases/sales; reserve requirement is a historical textbook lever (currently 0%)."},{"id":"M19","kind":"monetary","stem":"The Fed holds rates constant, buys bonds, and lowers textbook reserve requirements.","targets":[0,-1,1],"outcome":"expand","choices":["Both changes tend to make credit more available in the simplified model.","Bond purchases and bond sales have identical effects on banking-system reserves.","Changes in reserve requirements are voted on by the House and Senate, not the Fed.","The Fed’s policy tools cannot influence credit availability or economic demand."],"answer":"Both changes tend to make credit more available in the simplified model.","hint":"Rates and reserve requirements usually move opposite to expansion; bond purchases add reserves, sales remove them.","explain":"Both changes tend to make credit more available in the simplified model.","source":"https://www.federalreserve.gov/monetarypolicy.htm","where":"Federal Reserve Monetary Policy: interest-rate transmission and open-market purchases/sales; reserve requirement is a historical textbook lever (currently 0%)."},{"id":"M20","kind":"monetary","stem":"The Fed raises rates and raises reserve requirements but also buys bonds.","targets":[1,1,1],"outcome":"mixed","choices":["Two levers tighten credit while bond purchases add reserves; the combined magnitude is unknown.","Because the Fed purchased bonds, Congress must automatically increase income tax rates.","A higher policy rate necessarily increases borrowing because loans become cheaper.","The reserve requirement is currently a routinely adjusted positive percentage for all banks."],"answer":"Two levers tighten credit while bond purchases add reserves; the combined magnitude is unknown.","hint":"Rates and reserve requirements usually move opposite to expansion; bond purchases add reserves, sales remove them.","explain":"Two levers tighten credit while bond purchases add reserves; the combined magnitude is unknown.","source":"https://www.federalreserve.gov/monetarypolicy.htm","where":"Federal Reserve Monetary Policy: interest-rate transmission and open-market purchases/sales; reserve requirement is a historical textbook lever (currently 0%)."}];
'use strict';
const SCRIPT_URL='https://script.google.com/macros/s/AKfycbxENUBm5pd966tRn1g9R7HH0zSXcEI10LGLivzQzN0pn6b0ytZHJdV8HU9i0ihYtHJW/exec';
const TITLE='CS 20–21 Fiscal and Monetary Policy Review';
const KEY='gov-cs20-21-review-2026-multitool-v2';
const app=document.getElementById('app');
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
const shuffle=a=>{a=[...a];for(let i=a.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;};
const initial=()=>({started:false,done:false,index:0,items:[],attempts:0,misses:0,name:'',period:'',email:'',start:null,end:null,events:[],sessions:0,tabLeaves:0,copies:0,pastes:0,activeMs:0,awayMs:0,questionSeconds:[],lastSeen:Date.now(),away:false});
let S=initial(), timerId=null,locked=false,feedbackTimeout=null;
const storeKey=mail=>KEY+'::'+mail.toLowerCase();
const now=()=>new Date().toISOString();
const elapsed=()=>S.start?Math.floor((Date.now()-new Date(S.start).getTime())/1000):0;
const duration=()=>{let t=elapsed();return Math.floor(t/60)+':'+String(t%60).padStart(2,'0');};
function save(){if(S.email){try{localStorage.setItem(storeKey(S.email),JSON.stringify(S));}catch(e){}}}
function log(type,more={}){S.events.push({type,at:now(),question:S.index+1,...more});if(S.events.length>600)S.events=S.events.slice(-600);save();}
function newRun(){S=initial();S.started=true;S.start=now();S.sessions=1;S.items=shuffle(QUESTIONS).map(q=>({...q,options:shuffle(q.choices),missed:false,mastered:false,firstAttempt:null,attemptCount:0,seconds:0}));save();}
function load(mail){try{let v=JSON.parse(localStorage.getItem(storeKey(mail))||'null');if(!v||!Array.isArray(v.items)||v.items.length!==40)return false;S=v;S.sessions=(S.sessions||0)+1;S.started=true;S.lastSeen=Date.now();save();return true;}catch(e){return false;}}
function post(status){if(!S.email)return;let first=S.items.filter(q=>q.firstAttempt===true).length,mastered=S.items.filter(q=>q.mastered).length;let payload={action:'save',status,assignmentKey:KEY,assignmentTitle:TITLE,course:'Government',name:S.name,period:S.period,email:S.email,score:mastered,total:40,percent:Math.round(first/40*100),firstAttemptScore:first,masteryScore:mastered,attempts:S.attempts,startedAt:S.start,completedAt:S.end||'',elapsed:duration(),sessions:S.sessions,tabLeaves:S.tabLeaves,copies:S.copies,pastes:S.pastes,activeMs:S.activeMs,awayMs:S.awayMs,questionSeconds:S.items.map(q=>q.seconds||0),events:S.events,gameState:S};fetch(SCRIPT_URL,{method:'POST',mode:'no-cors',headers:{'Content-Type':'text/plain;charset=utf-8'},body:JSON.stringify(payload)}).catch(()=>{});}
function frame(content){app.innerHTML=`<a class="back" href="../../">← Back to Government Hub</a><header class="hero"><div><div class="eyebrow">LEGEND MASTERY SERIES • AMERICAN GOVERNMENT</div><h1>${TITLE}</h1><p>Content Statements 20–21 • Fiscal and Monetary Policy</p><p class="sub">40 OST-style applications. Set every policy tool, predict the economic direction, and defend your reasoning. First-attempt accuracy is preserved.</p></div><div class="pills"><span>40 Questions</span><span>2–3 Tools per Case</span><span>Hints after Misses</span><span>Mastery 100%</span></div></header>${content}`;}
function opening(){frame(`<section class="student-panel"><div class="eyebrow">STUDENT INFORMATION</div><h2>Enter your information to begin</h2><p class="sub">Use the same school email to retrieve your saved run.</p><div class="fields"><label>Full name<input id="studentName" placeholder="e.g., Jordan Smith" autocomplete="name"></label><label>Class period<select id="studentPeriod"><option value="">Choose</option>${[1,2,3,4,5,6,7,8].map(n=>`<option value="${n}">${n}</option>`).join('')}</select></label><label>School email<input id="studentEmail" type="email" placeholder="name@school.org" autocomplete="email"></label></div><div class="actions"><button id="start">Start / Continue</button><button class="secondary" id="load">Load previous work</button></div><p id="notice" role="status"></p></section>`);
const get=()=>({name:document.getElementById('studentName').value.trim(),period:document.getElementById('studentPeriod').value,email:document.getElementById('studentEmail').value.trim().toLowerCase()});
function valid(x){if(!x.name||!x.period||!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(x.email)){document.getElementById('notice').textContent='Please enter your name, class period, and a valid school email.';return false;}return true;}
document.getElementById('start').onclick=()=>{let x=get();if(!valid(x))return;if(!load(x.email))newRun();S.name=x.name;S.period=x.period;S.email=x.email;log('start');post('in_progress');render();};
document.getElementById('load').onclick=()=>{let x=get();if(!x.email){document.getElementById('notice').textContent='Enter the same school email used for your saved run.';return;}if(load(x.email)){render();return;}document.getElementById('notice').textContent='No saved run found in this browser. You may start a new run.';};}
const tools={fiscal:[['Taxes','Raise taxes','Keep taxes steady','Lower taxes'],['Government spending','Increase spending','Keep spending steady','Decrease spending']],monetary:[['Fed policy interest rate','Raise rate','Keep rate steady','Lower rate'],['Reserve requirement (textbook model)','Raise requirement','Keep requirement steady','Lower requirement'],['Open-market operations','Buy bonds','No bond trade','Sell bonds']]};
function slider(q,i){let fiscal=q.kind==='fiscal';let labels=tools[q.kind][i];let names=fiscal?(i===0?['Lower','Steady','Higher']:['Lower','Steady','Higher']):i===2?['Sell','Hold','Buy']:['Lower','Steady','Higher'];return `<div class="lever"><div class="lever-title">${esc(labels[0])}</div><div class="lever-body"><span class="end-label">${names[2]}</span><input class="vertical" type="range" min="-1" max="1" step="1" value="0" data-lever="${i}" aria-label="${esc(labels[0])}"><span class="end-label">${names[0]}</span></div><div class="lever-readout" id="readout${i}">Not set</div><div class="lever-controls"><button type="button" class="nudge" data-lever="${i}" data-set="-1" aria-label="Set ${esc(labels[0])} down">−</button><button type="button" class="nudge" data-lever="${i}" data-set="0" aria-label="Keep ${esc(labels[0])} steady">0</button><button type="button" class="nudge" data-lever="${i}" data-set="1" aria-label="Set ${esc(labels[0])} up">+</button></div></div>`;}
function render(){clearTimeout(feedbackTimeout);locked=false;if(!S.started){opening();return;}if(S.index>=40){finish();return;}let q=S.items[S.index];let first=S.items.filter(x=>x.firstAttempt===true).length;frame(`<div class="workspace"><section class="question-panel"><div class="eyebrow">${q.kind==='fiscal'?'FISCAL POLICY • CONGRESS':'MONETARY POLICY • FEDERAL RESERVE'}</div><div class="metrics"><div><b>${S.index+1} / 40</b><small>Question</small></div><div><b>${Math.round(first/40*100)}%</b><small>First-attempt total</small></div><div><b>${S.attempts}</b><small>Total attempts</small></div><div><b id="clock">${duration()}</b><small>Elapsed</small></div></div><div class="progress"><span style="width:${S.index/40*100}%"></span></div><h2>${esc(q.stem)}</h2><p class="instruction">Move <b>every</b> slider to match the scenario, including tools that stay unchanged. Then choose the best economic interpretation. The box is a model, not an answer indicator.</p><div class="levers">${q.targets.map((_,i)=>slider(q,i)).join('')}</div><div class="economy"><div class="economy-heading">${q.kind==='fiscal'?'ECONOMIC DEMAND':'MONEY SUPPLY / CREDIT CONDITIONS'}</div><div class="economy-box" id="economyBox"><span>MODEL PREVIEW</span><strong id="boxText">Adjust all tools</strong></div><small>Box size responds to your settings, but it does not reveal whether the settings answer the scenario.</small></div><h3>Which interpretation best follows from your chosen policy mix?</h3><div class="choices">${q.options.map((c,i)=>`<button type="button" class="choice" data-answer="${i}"><span class="letter">${'ABCD'[i]}.</span> ${esc(c)}</button>`).join('')}</div><div class="actions"><button id="apply" disabled>Apply policy and submit answer</button><button id="reset" class="secondary">Restart assignment</button></div><div class="feedback" id="feedback" role="status"></div><div class="source"><a href="${esc(q.source)}" target="_blank" rel="noopener noreferrer">Open supporting source ↗</a><div><b>Where to look:</b> ${esc(q.where)}</div></div></section><aside class="side-panel"><div class="eyebrow">HOW TO REASON</div><h3>Work through the entire chain</h3><p>1. Identify the economic problem.</p><p>2. Set each tool—including unchanged tools.</p><p>3. Predict the effect on demand, credit, or inflation.</p><p>4. Compare closely competing explanations.</p><hr><h3>Scoring</h3><p>First attempt is recorded. Incorrect answers receive a hint, and you must correct them for mastery.</p><p><b>Important Fed distinction:</b> Reserve requirements are a textbook tool. Actual U.S. reserve requirement ratios have been zero since March 2020.</p><button id="save" class="secondary">Save progress</button><p id="saved" class="sub"></p></aside></div>`);
let touched=new Set(),vals=q.targets.map(()=>0),buttons=[...document.querySelectorAll('.choice')];let selected=-1;
function update(){q.targets.forEach((_,i)=>{let value=vals[i],r=document.getElementById('readout'+i);r.textContent=value===0?'No change':value>0?'Increase / buy':'Decrease / sell';r.classList.toggle('touched',touched.has(i));});let score=q.kind==='fiscal'?-vals[0]+vals[1]:-vals[0]-vals[1]+vals[2];let scale=Math.max(.72,Math.min(1.22,1+score*.065));document.getElementById('economyBox').style.transform=`scale(${scale})`;document.getElementById('boxText').textContent=touched.size===q.targets.length?'Model updated':'Adjust all tools';document.getElementById('apply').disabled=touched.size!==q.targets.length||selected<0||locked;}
document.querySelectorAll('input.vertical').forEach(el=>el.oninput=()=>{let i=+el.dataset.lever;vals[i]=+el.value;touched.add(i);update();});document.querySelectorAll('.nudge').forEach(b=>b.onclick=()=>{let i=+b.dataset.lever;vals[i]=+b.dataset.set;touched.add(i);document.querySelector(`input[data-lever="${i}"]`).value=vals[i];update();});buttons.forEach((b,i)=>b.onclick=()=>{if(locked)return;selected=i;buttons.forEach(x=>x.classList.remove('selected'));b.classList.add('selected');update();});
document.getElementById('apply').onclick=()=>{if(locked||touched.size!==q.targets.length||selected<0)return;S.attempts++;q.attemptCount++;let toolsCorrect=vals.every((v,i)=>v===q.targets[i]),answerCorrect=q.options[selected]===q.answer,correct=toolsCorrect&&answerCorrect;if(q.firstAttempt===null)q.firstAttempt=correct;if(!correct){q.missed=true;S.misses++;let msg=!toolsCorrect&&!answerCorrect?'Both the tool settings and the interpretation need another look.':!toolsCorrect?'Your interpretation may fit, but one or more tool settings do not match the scenario.':'The levers match the scenario, but the predicted effect needs revision.';document.getElementById('feedback').innerHTML=`<strong>Not yet — try again.</strong><p>${msg} ${esc(q.hint)}</p>`;document.getElementById('feedback').className='feedback hint';log('incorrect',{id:q.id,toolsCorrect,answerCorrect,settings:vals});post('in_progress');return;}locked=true;q.mastered=true;document.querySelectorAll('button.choice,input.vertical,button.nudge,#apply').forEach(x=>x.disabled=true);document.getElementById('feedback').innerHTML=`<strong>Correct — all tools and reasoning align.</strong><p>${esc(q.explain)}</p>`;document.getElementById('feedback').className='feedback good';log('correct',{id:q.id,firstTry:!q.missed});post('in_progress');feedbackTimeout=setTimeout(()=>{S.index++;save();render();},4000);};
document.getElementById('reset').onclick=()=>{if(confirm('Restart all 40 questions? Previous first-attempt results already submitted remain recorded.')){let x={name:S.name,period:S.period,email:S.email};newRun();Object.assign(S,x);log('restart');post('in_progress');render();}};document.getElementById('save').onclick=()=>{log('manual_save');post('in_progress');document.getElementById('saved').textContent='Saved in this browser; progress sent to teacher endpoint.';};update();}
function finish(){S.done=true;if(!S.end){S.end=now();log('complete');post('submitted');}let first=S.items.filter(q=>q.firstAttempt===true).length;frame(`<section class="completion"><div class="eyebrow">COMPLETION TICKET • MASTERY</div><h2>${esc(TITLE)}</h2><p><b>${esc(S.name)}</b> • Period ${esc(S.period)} • ${esc(S.email)}</p><div class="metrics"><div><b>${first}/40</b><small>First-attempt score</small></div><div><b>40/40</b><small>Mastery</small></div><div><b>${S.attempts}</b><small>Total attempts</small></div><div><b>${duration()}</b><small>Elapsed</small></div></div><p>Assignment key: ${KEY}</p><button id="again">Start a new run</button></section>`);document.getElementById('again').onclick=()=>{let x={name:S.name,period:S.period,email:S.email};newRun();Object.assign(S,x);log('restart');render();};}
setInterval(()=>{if(S.started&&!S.done){let dt=Math.max(0,Math.min(5000,Date.now()-(S.lastSeen||Date.now())));if(S.away)S.awayMs+=dt;else{S.activeMs+=dt;if(S.items[S.index])S.items[S.index].seconds=(S.items[S.index].seconds||0)+dt/1000;}S.lastSeen=Date.now();let el=document.getElementById('clock');if(el)el.textContent=duration();save();}},1000);
document.addEventListener('visibilitychange',()=>{if(!S.started||S.done)return;S.away=document.hidden;if(S.away)S.tabLeaves++;S.lastSeen=Date.now();log(S.away?'tab_leave':'tab_return');});document.addEventListener('copy',()=>{if(S.started&&!S.done){S.copies++;log('copy');}});document.addEventListener('paste',()=>{if(S.started&&!S.done){S.pastes++;log('paste');}});window.addEventListener('beforeunload',save);
opening();
